import itertools
import networkx as nx
import matplotlib.pyplot as plt

def calculate_conditional_probability(rcas):
    products = set()
    product_pairs = []
    conditional_probs = {}

    # 遍历RCA字典，收集产品和产品对
    for product, country_list in rcas.items():
        products.add(product)
    
    # 生成产品两两组合
    product_pairs = list(itertools.combinations(products, 2))

    # 计算条件概率
    for product_pair in product_pairs:
        product1, product2 = product_pair
        common_countries = set(rcas[product1]) & set(rcas[product2])
        num_common_countries = len(common_countries)
        num_total_countries = len(set(itertools.chain.from_iterable(rcas.values())))

        conditional_prob = min(num_common_countries / len(rcas[product1]), num_common_countries / len(rcas[product2]), num_common_countries / num_total_countries) if len(rcas[product1]) > 0 and len(rcas[product2]) > 0 else 0
        conditional_probs[product_pair] = conditional_prob

    return conditional_probs

def build_product_network(conditional_probs):
    # 创建空的无向图
    G = nx.Graph()

    # 添加产品节点
    products = set()
    for product_pair in conditional_probs.keys():
        product1, product2 = product_pair
        products.add(product1)
        products.add(product2)
    G.add_nodes_from(products)

    # 添加临近度为边
    for product_pair, conditional_prob in conditional_probs.items():
        product1, product2 = product_pair
        if conditional_prob > 0:  # 只添加邻近度大于0的边
            G.add_edge(product1, product2, weight=conditional_prob)

    return G

